INSERT INTO `dim_stocks` (`ticker`, `company_name`, `label_delisted`, `Sector`, `Primary_Sector`, `Sub_Sector`, `Core_Business_Product_Service`, `stock_status`, `status_reason`, `status_set_by`, `status_set_at`) VALUES
	('AADI', 'Adaro Andalan Indonesia Tbk.', 0, 'Energi', 'Pertambangan', 'Batubara', 'Menambang dan menjual batu bara termal serta menyediakan jasa penunjang pertambangan sebagai bagian dari Grup Adaro.', 'blacklist', '- Perusahaan beroperasi secara legal dan IPO dilakukan melalui mekanisme resmi pasar modal Indonesia/OJK. - Bisnis utama sudah berjalan dan menghasilkan, bukan perusahaan tahap awal yang belum terbukti. - Aset operasionalnya nyata: tambang, logistik, kapal tunda, tongkang, floating crane, dan infrastruktur pendukung. - Sebagian dana IPO dipakai untuk kebutuhan operasional nyata, yaitu memperkuat armada logistik melalui MBP. - Penguatan logistik bisa menurunkan ketergantungan pada pihak ketiga dan menjaga kelancaran pengiriman batu bara. - Perusahaan punya basis pelanggan besar dan menargetkan pelanggan blue-chip dengan kontrak jangka panjang. - Kebijakan kredit pelanggan cukup konservatif, termasuk penggunaan Letter of Credit untuk pelanggan baru. - Perusahaan mengakui dan mencadangkan kewajiban lingkungan seperti reklamasi dan rehabilitasi tambang. - Ada penempatan jaminan reklamasi dalam bentuk bank garansi/deposito, sehingga tanggung jawab lingkungan tidak sepenuhnya diabaikan. - Prospektus cukup transparan mengungkap risiko: lahan, lingkungan, cuaca, regulasi, harga batu bara, dan operasional. - Ada inisiatif menuju operasi lebih hijau, seperti panel surya, elektrifikasi pompa air, dan rencana kendaraan listrik di tambang. - Ada diversifikasi pendukung seperti logistik, air, lahan, biomassa/woodchip, bukan hanya murni jual batu bara. - Perusahaan memiliki rencana dividen, meskipun kebijakan dividen tidak mengikat secara hukum. - Grup usaha berada di bawah ekosistem Adaro yang sudah punya rekam jejak panjang di industri energi dan tambang. - Jadi, berdasarkan prospektus, alasan whitelist adalah: legal, aset nyata, cashflow kuat, operasional matang, risiko diungkap, dan ada rencana pengelolaan lingkungan serta logistik yang jelas.', 'xoot', '2026-09-06 08:24:38'),
